                m.insert(QString::fromUtf8(u8"<html><head/><body><p>Select how you would like to install <i>The Elder Scrolls III: Morrowind</i>.</p></body></html>"), QString::fromUtf8(u8"<html><head/><body><p>\u0412\u044B\u0431\u0435\u0440\u0438\u0442\u0435 \u0441\u043F\u043E\u0441\u043E\u0431 \u0443\u0441\u0442\u0430\u043D\u043E\u0432\u043A\u0438 <i>The Elder Scrolls III: Morrowind</i>.</p></body></html>"));
                m.insert(QString::fromUtf8(u8"<html><head/><body><p>Select which official Morrowind expansions should be installed. For best results, it is recommended to have both expansions installed.</p><p><span style=\" font-weight:bold;\">Note:</span> It is possible to install expansions later by re-running this Wizard.<br/></p></body></html>"), QString::fromUtf8(u8"<html><head/><body><p>\u0412\u044B\u0431\u0435\u0440\u0438\u0442\u0435 \u043E\u0444\u0438\u0446\u0438\u0430\u043B\u044C\u043D\u044B\u0435 \u0434\u043E\u043F\u043E\u043B\u043D\u0435\u043D\u0438\u044F Morrowind. \u0420\u0435\u043A\u043E\u043C\u0435\u043D\u0434\u0443\u0435\u0442\u0441\u044F \u0443\u0441\u0442\u0430\u043D\u043E\u0432\u0438\u0442\u044C \u043E\u0431\u0430.</p><p><span style=\" font-weight:bold;\">\u041F\u0440\u0438\u043C\u0435\u0447\u0430\u043D\u0438\u0435:</span> \u0414\u043E\u043F\u043E\u043B\u043D\u0435\u043D\u0438\u044F \u043C\u043E\u0436\u043D\u043E \u0443\u0441\u0442\u0430\u043D\u043E\u0432\u0438\u0442\u044C \u043F\u043E\u0437\u0436\u0435, \u0441\u043D\u043E\u0432\u0430 \u0437\u0430\u043F\u0443\u0441\u0442\u0438\u0432 \u043C\u0430\u0441\u0442\u0435\u0440.<br/></p></body></html>"));
                m.insert(QString::fromUtf8(u8"<html><head/><body><p>Morrowind.ini import is optional. The selected Data Files folder, base masters and BSA archives are configured automatically.</p><p><span style=\" font-weight:bold;\">Note:</span> It is possible to import settings later by re-running this Wizard.</p><p/></body></html>"), QString::fromUtf8(u8"<html><head/><body><p>\u0418\u043C\u043F\u043E\u0440\u0442 Morrowind.ini \u043D\u0435\u043E\u0431\u044F\u0437\u0430\u0442\u0435\u043B\u0435\u043D. \u0412\u044B\u0431\u0440\u0430\u043D\u043D\u0430\u044F \u043F\u0430\u043F\u043A\u0430 Data Files, \u0431\u0430\u0437\u043E\u0432\u044B\u0435 ESM \u0438 BSA \u043D\u0430\u0441\u0442\u0440\u0430\u0438\u0432\u0430\u044E\u0442\u0441\u044F \u0430\u0432\u0442\u043E\u043C\u0430\u0442\u0438\u0447\u0435\u0441\u043A\u0438.</p><p><span style=\" font-weight:bold;\">\u041F\u0440\u0438\u043C\u0435\u0447\u0430\u043D\u0438\u0435:</span> \u041D\u0430\u0441\u0442\u0440\u043E\u0439\u043A\u0438 \u043C\u043E\u0436\u043D\u043E \u0438\u043C\u043F\u043E\u0440\u0442\u0438\u0440\u043E\u0432\u0430\u0442\u044C \u043F\u043E\u0437\u0436\u0435, \u0441\u043D\u043E\u0432\u0430 \u0437\u0430\u043F\u0443\u0441\u0442\u0438\u0432 \u043C\u0430\u0441\u0442\u0435\u0440.</p><p/></body></html>"));
                m.insert(QString::fromUtf8(u8"Delete saved cell state while keeping player accounts and world data."), QString::fromUtf8(u8"\u0423\u0434\u0430\u043B\u0438\u0442\u044C \u0441\u043E\u0445\u0440\u0430\u043D\u0451\u043D\u043D\u044B\u0435 \u0441\u043E\u0441\u0442\u043E\u044F\u043D\u0438\u044F \u044F\u0447\u0435\u0435\u043A, \u0441\u043E\u0445\u0440\u0430\u043D\u0438\u0432 \u0430\u043A\u043A\u0430\u0443\u043D\u0442\u044B \u0438\u0433\u0440\u043E\u043A\u043E\u0432 \u0438 \u0434\u0430\u043D\u043D\u044B\u0435 \u043C\u0438\u0440\u0430."));
